        and s.skin_name like concat('%', #{skinName}, '%')



        and s.weapon_type_id = #{weaponTypeId}



        and s.quality_id = #{qualityId}



        and s.status = #{status}



        and exists (select 1 from debuff_skin_listing sl where sl.skin_id = s.id and sl.status = 0)


order by s.id asc

select s.id as skin_id, s.skin_name, s.image_url, s.min_price, wt.weapon_name, wt.weapon_category, sq.quality_name, sq.quality_color, min(sl.price) as lowest_price, count(sl.id) as listing_count, (select wear_name from debuff_inventory i where i.skin_id = s.id and i.status in (0, 1) limit 1) as wear_name, (select sl2.id from debuff_skin_listing sl2 where sl2.skin_id = s.id and sl2.status = 0 order by sl2.price asc limit 1) as first_listing_id from debuff_skin s left join debuff_weapon_type wt on s.weapon_type_id = wt.id left join debuff_skin_quality sq on s.quality_id = sq.id left join debuff_skin_listing sl on s.id = sl.skin_id and sl.status = 0
s.status = '0'
and wt.weapon_category = #{weaponCategoryId}
and s.weapon_type_id = #{weaponTypeId}
and s.quality_id = #{qualityId}
and sl.price >= #{minPrice}
and sl.price <= #{maxPrice}
and s.skin_name like concat('%', #{keyword}, '%')
group by s.id, s.skin_name, s.image_url, s.min_price, s.create_time, wt.weapon_name, wt.weapon_category, sq.quality_name, sq.quality_color
having count(sl.id) > 0
order by lowest_price asc order by lowest_price desc order by s.create_time desc order by listing_count desc

